BEGIN;
CREATE TABLE IF NOT EXISTS dei_tenants(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS dei_tenant_memberships(tenant_id UUID NOT NULL REFERENCES dei_tenants(id),user_id INTEGER NOT NULL REFERENCES users(id),role TEXT NOT NULL CHECK(role IN('data_steward','analyst','qualified_reviewer','case_manager','auditor','admin')),active BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS dei_source_syncs(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dei_tenants(id),provider TEXT NOT NULL,cursor TEXT,status TEXT NOT NULL CHECK(status IN('pending','running','succeeded','failed')),attempts INTEGER NOT NULL DEFAULT 0,records_read INTEGER NOT NULL DEFAULT 0,records_rejected INTEGER NOT NULL DEFAULT 0,failure_code TEXT,failure_detail TEXT,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,UNIQUE(tenant_id,provider,cursor));
CREATE TABLE IF NOT EXISTS dei_analyses(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dei_tenants(id),dataset_id TEXT NOT NULL,dataset_manifest JSONB NOT NULL,metric_definition JSONB NOT NULL,analysis_hash CHAR(64) NOT NULL,lawful_purpose TEXT NOT NULL,status TEXT NOT NULL DEFAULT'registered' CHECK(status IN('registered','validated','analyzed','qualified_review','changes_requested','approved','intervention_active','measured')),idempotency_key TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 0,created_by INTEGER NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key),UNIQUE(tenant_id,analysis_hash));
CREATE TABLE IF NOT EXISTS dei_results(id BIGSERIAL PRIMARY KEY,analysis_id BIGINT NOT NULL REFERENCES dei_analyses(id),cohort_key TEXT NOT NULL,suppressed BOOLEAN NOT NULL,count_value INTEGER,value JSONB,uncertainty JSONB,missingness JSONB,computed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CHECK((suppressed AND count_value IS NULL AND value IS NULL)OR NOT suppressed),UNIQUE(analysis_id,cohort_key));
CREATE TABLE IF NOT EXISTS dei_reviews(id BIGSERIAL PRIMARY KEY,analysis_id BIGINT NOT NULL REFERENCES dei_analyses(id),reviewer_id INTEGER NOT NULL REFERENCES users(id),qualification_reference TEXT NOT NULL,decision TEXT NOT NULL CHECK(decision IN('approved','changes_requested')),interpretation TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS dei_interventions(id BIGSERIAL PRIMARY KEY,analysis_id BIGINT NOT NULL REFERENCES dei_analyses(id),owner_id INTEGER NOT NULL REFERENCES users(id),title TEXT NOT NULL,outcome_metric TEXT NOT NULL,baseline JSONB NOT NULL,target JSONB NOT NULL,review_date DATE NOT NULL,status TEXT NOT NULL DEFAULT'planned',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS dei_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES dei_tenants(id),analysis_id BIGINT REFERENCES dei_analyses(id),actor_id INTEGER REFERENCES users(id),action TEXT NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS dei_analysis_queue_idx ON dei_analyses(tenant_id,status,updated_at);
COMMIT;
